entries[124445] = { ["name"] = "Glyph of Fists of Fury", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nWhen channeling Fists of Fury, your parry chance is increased by 100%." }
entries[124446] = { ["name"] = "Glyph of Clash", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMajor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the range of your Clash ability by 10 yards." }
entries[124447] = { ["name"] = "Glyph of Enduring Healing Sphere", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nClasses: Monk\n25\nUse:" }
entries[124448] = { ["name"] = "Glyph of Rapid Rolling", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMajor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nFor 5 sec seconds after using Roll or Chi Torpedo, your next Roll or Chi Torpedo will go 30% farther." }
entries[124449] = { ["name"] = "Glyph of Guard", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMajor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the amount your Guard absorbs by 10%, but your Guard can only absorb magical damage." }
entries[124450] = { ["name"] = "Glyph of Mana Tea", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMajor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nYour Mana Tea is instant instead of channeled and consumes two stacks when used, but causes a 10 sec cooldown." }
entries[124451] = { ["name"] = "Glyph of Zen Meditation", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nYou can now channel Zen Meditation while moving." }
entries[124452] = { ["name"] = "Glyph of Renewing Mists", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nYour Renewing Mist travels to the furthest injured target within 40 yards rather than the closest injured target within 20 yards." }
entries[124453] = { ["name"] = "Glyph of Spinning Crane Kick", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nYou move at full speed while channeling Spinning Crane Kick." }
entries[124454] = { ["name"] = "Glyph of Spinning Fire Blossom", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nYour Spinning Fire Blossom requires an enemy target rather than traveling in front of you, but is no longer capable of rooting targets." }
entries[124455] = { ["name"] = "Glyph of Surging Mist", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nYour Surging Mist no longer requires a target, and instead heals the lowest health target within 40 yards." }
entries[124456] = { ["name"] = "Glyph of Touch of Death", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nYour Touch of Death no longer has a Chi cost, but the cooldown is increased by 2 minutes." }
entries[124457] = { ["name"] = "Glyph of Transcendence", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMajor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nReduces the cooldown of your Transcendence: Transfer spell by 5 sec." }
entries[124458] = { ["name"] = "Healing Sphere", ["text"] = "Unlimited range\nInstant\nYou form a Healing Sphere out of healing mists at the target location for 1 min. If allies walk through it, they consume the sphere, healing themselves for [((Attack Power * 0.75) + 9986 )] .\n\nMaximum of 3 Healing Spheres can be active by the Monk at any given time.\n\nIf the Healing Sphere expires before being used, an ally nearby within 6 yards of the sphere will be healed for 50% of the effect." }
entries[124459] = { ["name"] = "Glyph of Mind Flay", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Celestial Ink (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nYour Mind Flay spell no longer slows your victim's movement speed. Instead, each time Mind Flay deals damage you will be granted 15% increased movement speed for 5 sec, stacking up to 3 times." }
entries[124460] = { ["name"] = "Glyph of Vampiric Embrace", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nYour Vampiric Embrace converts an additional 50% of the damage you deal into healing, but the duration is reduced by 5 sec." }
entries[124461] = { ["name"] = "Glyph of Shadow Word: Death", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nYour Shadow Word: Death can now be cast at any time, but deals 25% damage against targets above 20% health [ Mind Flay : and does not generate a Shadow Orb when used against them ].\n\nCasting Shadow Word: Death now also does damage to you equivalent to the damage it would do to an enemy above 20% health." }
entries[124463] = { ["name"] = "Glyph of Fortuitous Spheres", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nFalling below 25% health will automatically summon a healing sphere near you at no cost. This effect cannot occur more often than once every 30 seconds. (30s cooldown)" }
entries[124464] = { ["name"] = "Shadow Word: Pain", ["text"] = "100 yd range\nInstant\nA word of darkness that causes 780 Shadow damage instantly, and an additional ( 4678 - 780 ) Shadow damage over 18 sec." }
entries[124465] = { ["name"] = "Vampiric Touch", ["text"] = "100 yd range\nInstant\nCauses 5 Shadow damage over 15 sec. Each time Vampiric Touch deals damage the caster gains 2% of maximum mana." }
entries[124466] = { ["name"] = "Glyph of the Heavens", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nYour Levitate targets will appear to be riding on a cloud for the duration of the spell." }
entries[124467] = { ["name"] = "Devouring Plague", ["text"] = "100 yd range\nInstant\nConsumes all of the caster's Shadow Orbs to deal 0 Shadow damage and an additional 0 Shadow damage every 1.00 sec for 6 sec. Also heals the caster for 1% of their maximum health when it deals periodic damage.\n\nDamage and healing increased based on the number of Shadow Orbs consumed. [ Solace and Insanity : While Devouring Plague is active, damage from your Mind Flay is increased by 33% per orb consumed ]" }
entries[124468] = { ["name"] = "Mind Flay", ["text"] = "100 yd range\nInstant\nAssault the target's mind with Shadow energy, causing 3148 Shadow damage over 3 sec [ Glyph of Mind Flay : Each time Mind Flay deals damage the Priest will be granted 15% increased movement speed for 5 sec, stacking up to 3 times / and slowing their movement speed by 50%.]" }
